contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params correspond to requestLoan inputs
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        // avoid division by zero in collateralFor (used inside requestLoan)
        require(loanToCollateral_ != 0);

        bool reverted;
        uint256 reqID;
        // call requestLoan and capture revert
        uint256 id = c.requestLoan(amount_, interest_, loanToCollateral_, duration_); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            reqID = type(uint256).max;
        } else {
            reverted = false;
            reqID = id;
        }

        // General property: if the call did not revert, then the created request must be active
        assert(reverted || c.isActive(reqID));
    }

    receive() external payable {}
}

